() => {
  const btns = Array.from(document.querySelectorAll('button'));
  const btn = btns.find(b => b.textContent.includes('全链路数据血缘视图'));
  if (!btn) return { found: false };
  const rect = btn.getBoundingClientRect();
  return { found: true, text: btn.textContent.trim(), rect: {top: rect.top, left: rect.left, w: rect.width, h: rect.height} };
}

() => {
  const btns = Array.from(document.querySelectorAll('button'));
  const btn = btns.find(b => b.textContent.includes('全链路数据血缘视图'));
  if (!btn) return { clicked: false };
  btn.click();
  return { clicked: true };
}

() => {
  // Wait a moment for render
  const body = document.body.innerText;
  const hasLineage = body.includes('接入源') || body.includes('血缘') || body.includes('NL2SQL');
  return { hasLineage, sample: body.slice(0, 300) };
}

