() => {
  const docTop = (el) => el ? { top: el.getBoundingClientRect().top + window.scrollY, height: el.getBoundingClientRect().height } : null;
  const grid = [...document.querySelectorAll('div')].find(g => g.className && typeof g.className === 'string' && g.className.includes('lg:grid-cols-12'));
  const spans = [...document.querySelectorAll('span')];
  const topSpan = spans.find(s => s.textContent.includes('悬停任意决策简报或固化监控图表'));
  const botSpan = spans.find(s => s.textContent.includes('悬停或点击任意节点'));
  const topWrap = topSpan ? topSpan.closest('.relative') : null;
  const botWrap = botSpan ? botSpan.closest('.relative') : null;
  const overlay = topWrap ? topWrap.querySelector('.absolute') : null;
  return {
    pageHeight: document.documentElement.scrollHeight,
    gridTop: docTop(grid),
    topPlaceholder: docTop(topWrap),
    bottomPlaceholder: docTop(botWrap),
    overlayPresent: !!overlay,
    viewportH: window.innerHeight,
  };
}

() => {
  const de = document.documentElement, body = document.body;
  const scrollY = window.scrollY;
  // find the app-level scroll container
  const mains = [...document.querySelectorAll('main,div')].filter(el => el.scrollHeight > el.clientHeight + 50);
  const scrollers = mains.slice(0, 8).map(el => ({ tag: el.tagName, cls: (el.className||'').toString().slice(0,60), sh: el.scrollHeight, ch: el.clientHeight }));
  // widget cards
  const spans = [...document.querySelectorAll('span')];
  const groupLabel = spans.find(s => /^固化监控图表/.test(s.textContent.trim()) && s.textContent.includes('('));
  // find cards under widgets: elements whose text contains chart type; simpler: look for span text list
  return {
    scrollY,
    deScrollHeight: de.scrollHeight, bodyScrollHeight: body.scrollHeight,
    deOffsetHeight: de.offsetHeight, bodyOffsetHeight: body.offsetHeight,
    bodyRect: body.getBoundingClientRect().height,
    scrollers,
  };
}

() => {
  const sc = [...document.querySelectorAll('div')].find(el => el.className.toString().includes('flex-1 overflow-y-auto'));
  const spans = [...document.querySelectorAll('span')];
  const topSpan = spans.find(s => s.textContent.includes('悬停任意决策简报或固化监控图表'));
  const topWrap = topSpan.closest('.relative');
  // scroll so placeholder is near top of view
  const scRect = sc.getBoundingClientRect();
  const wrapRect = topWrap.getBoundingClientRect();
  sc.scrollTop = sc.scrollTop + (wrapRect.top - scRect.top) - 20;
  return { scrollTop: sc.scrollTop, scrollHeight: sc.scrollHeight, clientHeight: sc.clientHeight };
}

() => {
  const all = [...document.querySelectorAll('*')];
  const scrollers = all.filter(el => el.scrollHeight > el.clientHeight + 50 && el.clientHeight > 100)
    .map(el => ({ tag: el.tagName, cls: (el.className||'').toString().slice(0,80), sh: el.scrollHeight, ch: el.clientHeight, st: el.scrollTop }));
  const hasLineage = document.body.innerText.includes('全域数据血缘');
  return { scrollers: scrollers.slice(0, 10), hasLineage };
}

() => {
  const headings = [...document.querySelectorAll('h2')].filter(h => h.textContent.includes('全域数据血缘'));
  if (!headings.length) return { found: false };
  const h = headings[0];
  // walk up parents
  const chain = [];
  let el = h;
  while (el && el !== document.body) {
    const r = el.getBoundingClientRect();
    chain.push({ tag: el.tagName, cls: (el.className||'').toString().slice(0,70), h: Math.round(r.height), top: Math.round(r.top) });
    el = el.parentElement;
  }
  return { found: true, chain };
}

() => {
  const sc = [...document.querySelectorAll('div')].find(el => el.className.toString().startsWith('flex-1 overflow-y-auto bg-slate-950') && el.clientHeight > 500);
  const card = [...document.querySelectorAll('div')].find(d => d.className.toString().startsWith('bg-slate-900 border border-slate-800 rounded-3xl'));
  const scRect = sc.getBoundingClientRect();
  const cardRect = card.getBoundingClientRect();
  sc.scrollTop = sc.scrollTop + (cardRect.top - scRect.top) - 16;
  return { scrollTop: sc.scrollTop, scrollHeight: sc.scrollHeight };
}

() => {
  const sc = [...document.querySelectorAll('div')].find(el => el.className.toString().startsWith('flex-1 overflow-y-auto bg-slate-950') && el.clientHeight > 500);
  const info = { sh: sc.scrollHeight, ch: sc.clientHeight, st0: sc.scrollTop, overflow: getComputedStyle(sc).overflowY };
  sc.scrollTop = 600;
  info.st1 = sc.scrollTop;
