  return {
    overlayRect: { top: Math.round(oRect.top), bottom: Math.round(oRect.bottom), width: Math.round(oRect.width), height: Math.round(oRect.height) },
    overlayGreen: getComputedStyle(overlay).borderColor,
    flowOverflowX: getComputedStyle(flow).overflowX,
    flowScrollW: flow.scrollWidth, flowClientW: flow.clientWidth, flowH: Math.round(flow.getBoundingClientRect().height),
    chips,
    botText: botOverlay.innerText.replace(/\n/g,' | '),
    clippedByAncestors: clipped,
    viewportH: window.innerHeight,
    visibleInViewport: oRect.bottom <= window.innerHeight,
  };
}

async () => {
