async () => {
  const sc = [...document.querySelectorAll('div')].find(el => el.className.toString().startsWith('flex-1 overflow-y-auto bg-slate-950') && el.clientHeight > 500);
  const scRect = sc.getBoundingClientRect();
  const pos = (el) => el ? Math.round((el.getBoundingClientRect().top - scRect.top + sc.scrollTop) * 10) / 10 : null;
  const h = (el) => el ? Math.round(el.getBoundingClientRect().height * 10) / 10 : null;
  const h2 = [...document.querySelectorAll('h2')].find(x => x.textContent.includes('全域数据血缘'));
  const root = h2.closest('.bg-slate-900.rounded-3xl');
  const header = root.children[0], topWrap = root.children[1], grid = root.children[2], botWrap = root.children[3];
  const engineNode = [...document.querySelectorAll('div')].find(d => d.innerText && d.innerText.includes('NL2SQL 引擎') && d.className.toString().startsWith('p-4 rounded-2xl'));
  const m1 = { scrollTop: sc.scrollTop, scrollHeight: sc.scrollHeight, headerH: h(header), topWrapTop: pos(topWrap), gridTop: pos(grid), gridH: h(grid), botWrapTop: pos(botWrap) };
  await new Promise(r => setTimeout(r, 2000));
  const m2 = { scrollTop: sc.scrollTop, scrollHeight: sc.scrollHeight, headerH: h(header), topWrapTop: pos(topWrap), gridTop: pos(grid), gridH: h(grid), botWrapTop: pos(botWrap) };
  return { m1, m2, engineTitle: engineNode ? engineNode.innerText.split('\n')[0] : null, stable: JSON.stringify(m1) === JSON.stringify(m2) };
}
